/**
 * @name SSRF risk: untrusted URL passed to httpcore request methods
 * @description Finds flows from remote/user-controlled data into httpcore request URL parameters.
 * @kind path-problem
 * @problem.severity error
 * @id py/httpcore-ssrf
 * @tags security
 *       external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module HttpcoreSsrfConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode c |
      c = API::moduleImport("httpcore").getMember(["request", "stream"]).getACall() and
      sink = c.getArg(0)
    )
  }
}

module HttpcoreSsrfFlow = TaintTracking::Global<HttpcoreSsrfConfig>;
import HttpcoreSsrfFlow::PathGraph

from HttpcoreSsrfFlow::PathNode source, HttpcoreSsrfFlow::PathNode sink
where HttpcoreSsrfFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into httpcore request URL parameter $@.", source.getNode(), "untrusted URL"
